'use client'

import type { Route } from 'next'
import Link from 'next/link'
import { useRouter } from 'next/navigation'

export default function Example() {
	const router = useRouter()
	const slug = 'nextjs'

	return (
		<>
			{/* Link: literal and dynamic */}
			<Link href="/about" />
			<Link href={`/blog/${slug}`} />
			<Link href={('/blog/' + slug) as Route} />
			{/* TypeScript error if href is not a valid route */}
			<Link href="/aboot" />

			{/* Router: literal and dynamic strings are validated */}
			<button onClick={() => router.push('/about')}>Push About</button>
			<button onClick={() => router.replace(`/blog/${slug}`)}>Replace Blog</button>
			<button onClick={() => router.prefetch('/contact')}>Prefetch Contact</button>

			{/* For non-literal strings, cast to Route */}
			<button onClick={() => router.push(('/blog/' + slug) as Route)}>Push Non-literal Blog</button>
		</>
	)
}

import { NextRequest, NextResponse } from 'next/server'

export function proxy(request: NextRequest) {
	if (request.nextUrl.pathname === '/proxy-redirect') {
		return NextResponse.redirect(new URL('/', request.url))
	}

	return NextResponse.next()
}

